package ama.transcript;
import ama.contract.MinutesContracts.*;import ama.contract.ConfigArchiveContracts.ArchiveReadBudget;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import java.math.BigDecimal;import java.sql.*;import javax.sql.DataSource;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
/** Finite JDBC boundary tests. The real MySQL query and long edited transcript are verified separately. */
class MinutesMetadataAdmissionTest {
 final DataSource source=mock(DataSource.class);final Connection connection=mock(Connection.class);final List<String> statements=new ArrayList<>();int rawReads;long measuredCount=360,measuredBytes=50000,measuredScalars=50000,measuredUnits=50000;
 final String meeting="00000000-0000-4000-8000-000000000001";final List<Map<String,Object>> rows=new ArrayList<>();final List<MinutesGraphDiscovery.Selector> selectors=new ArrayList<>();
 MinutesMetadataAdmissionTest()throws Exception{
  for(int r=0;r<8;r++){String revision=new UUID(1,r+1).toString();selectors.add(new MinutesGraphDiscovery.Selector("transcript_segment","revision_id",revision,""));for(int n=0;n<45;n++){var row=new LinkedHashMap<String,Object>();row.put("revision_id",revision);row.put("segment_id",new UUID(2,n+1).toString());row.put("ordinal",(long)n+1);row.put("source_file_id",meeting);row.put("source_paragraph",(long)n+1);row.put("start_ms",null);row.put("end_ms",null);row.put("speaker_id",null);rows.add(row);}}
  when(source.getConnection()).thenReturn(connection);when(connection.prepareStatement(anyString())).thenAnswer(call->{String sql=call.getArgument(0);statements.add(sql);var statement=mock(PreparedStatement.class);when(statement.executeQuery()).thenAnswer(ignored->{var result=mock(ResultSet.class);if(sql.startsWith("SELECT COUNT(*)")){when(result.next()).thenReturn(true,false);when(result.getBigDecimal(anyString())).thenAnswer(arg->new BigDecimal(switch((String)arg.getArgument(0)){case "row_count"->measuredCount;case "utf8_bytes"->measuredBytes;case "scalar_count"->measuredScalars;case "utf16_units"->measuredUnits;default->throw new AssertionError("Unknown measurement");}));}else{rawReads++;var position=new AtomicInteger(-1);when(result.next()).thenAnswer(arg->position.incrementAndGet()<rows.size());when(result.getObject(anyString())).thenAnswer(arg->rows.get(position.get()).get(arg.getArgument(0)));}return result;});return statement;});
 }
 TranscriptAcquisitionBudget.Ledger ledger(){return new TranscriptAcquisitionBudget(1048576,1048576,1048576,16777216,16777216,1048576,128,256,256).ledger(new ArchiveReadBudget(65536,1048576,64,128,16,200000,32,255,65536,262144,1048576,65536,32,250000,500000),new CanonicalBudget(16777216,32,1000000,4194304,250000),()->false);}
 MinutesGraphDiscovery.Discovery discovery(){return new MinutesGraphDiscovery.Discovery(meeting,"CURRENT_GENERATION",null,Map.of(),Map.of("transcript_segment",rows),Map.of(),Set.of(),selectors);}
 @Test void eightEditsOf45ParagraphsFitTheActualMeasuredMetadataWithoutRaisingTheOneMiBEnvelope(){var budget=ledger();assertDoesNotThrow(()->MinutesGraphDiscovery.lockAndCompare(source,discovery(),"transcript_segment",budget));assertEquals(1,rawReads);assertEquals(2,statements.size());assertTrue(statements.getFirst().contains("FOR UPDATE)"));assertTrue(statements.getFirst().contains("LIMIT ?"));assertTrue(statements.getLast().endsWith("FOR UPDATE"));assertEquals(361,budget.usage()[5]);}
 @Test void sameAlreadyConsumedLedgerRejectsBeforeAnyRawMetadataTransfer(){var budget=ledger();budget.capture(900000,900000,900000,1);var failure=assertThrows(Failure.class,()->MinutesGraphDiscovery.lockAndCompare(source,discovery(),"transcript_segment",budget));assertEquals(FailureCode.BUDGET_EXCEEDED,failure.code());assertEquals(0,rawReads);assertTrue(budget.usage()[0]>=900000);}
 @Test void sentinelOrChangedMembershipFailsBeforeTransferringRawMetadata(){for(long count:new long[]{359,361}){measuredCount=count;var failure=assertThrows(Failure.class,()->MinutesGraphDiscovery.lockAndCompare(source,discovery(),"transcript_segment",ledger()));assertEquals(FailureCode.PROVENANCE_UNAVAILABLE,failure.code());assertEquals(0,rawReads);}}
 @Test void negativeOrOversizedMeasurementsNeverAuthorizeRawMetadata(){for(long bytes:new long[]{-1,1048577,Long.MAX_VALUE}){measuredBytes=bytes;assertThrows(Failure.class,()->MinutesGraphDiscovery.lockAndCompare(source,discovery(),"transcript_segment",ledger()));assertEquals(0,rawReads);}}
 @Test void measuredAdmissionStillComparesEveryActualMetadataCell(){var expected=discovery();var actual=new ArrayList<Map<String,Object>>(rows);var changed=new LinkedHashMap<>(rows.getFirst());changed.put("source_paragraph",999L);rows.set(0,changed);var declaration=new MinutesGraphDiscovery.Discovery(meeting,"CURRENT_GENERATION",null,Map.of(),Map.of("transcript_segment",actual),Map.of(),Set.of(),selectors);var failure=assertThrows(Failure.class,()->MinutesGraphDiscovery.lockAndCompare(source,declaration,"transcript_segment",ledger()));assertEquals(FailureCode.PROVENANCE_UNAVAILABLE,failure.code());assertEquals(1,rawReads);}
}
